for(case in cases) {
 m<-case$model;p<-predict_pd(m,case$X,feature_order=unlist(m$feature_order),expected_target=m$target,context=list(known_at='2024-01-01'))
 stopifnot(max(abs(unlist(p$value)-unlist(case$expected)))<2e-15,p$diagnostics$prediction_count==length(case$expected),p$diagnostics$training_known_at=='2023-12-01',p$diagnostics$calibration_applied=='NONE_IMPLICIT')
 err<-tryCatch(predict_pd(m,case$X,feature_order=unlist(m$feature_order),expected_target=m$target,context=list(known_at='2023-11-30')),creditratingsystem_error=identity)
 stopifnot(inherits(err,'creditratingsystem_error'),err$code=='LOOKAHEAD_BIAS')
 # Legacy batch also preserves categorical/sequence/grouped input structure.
 reg<-register_rating_model_version(NULL,list(model=m,dependencies=setNames(list(),character()),configuration=setNames(list(),character())),list(model_id=m$model_id,model_version=m$model_version,registered_at='2023-12-15'))$value
 req<-list(row_id=case$id,known_at='2024-01-01',model_id=m$model_id,model_version=m$model_version,model_hash=reg$entries[[1]]$model_hash,recipe=list(method='pd_model',version='1.0',parameters=list(expected_target=m$target)),input=list(X=case$X,feature_order=m$feature_order))
 row<-rate_subject_batch(list(req),reg,'typed','2024-01-01')$value$rows[[1]]
 stopifnot(row$status=='OK',max(abs(unlist(row$value)-unlist(case$expected)))<2e-15)
}
spoof<-cases[[2]]$model;spoof$method_id<-'classification.fit_sequence_pd'
err<-tryCatch(predict_pd(spoof,cases[[2]]$X,feature_order='x',expected_target=spoof$target),creditratingsystem_error=identity)
stopifnot(inherits(err,'creditratingsystem_error'),err$code=='INVALID_MODEL')
